pub fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    let n = n as usize;
    let k = k as i16;

    let considered = participations.len().min(n);

    let mut eligible: u16 = 0;
    for &p in participations.iter().take(considered) {
        // Eligibility: 5 - p >= k  <=>  p <= 5 - k
        // We compute in a signed type to avoid any underflow concerns.
        if (5i16 - p as i16) >= k {
            eligible += 1;
        }
    }

    (eligible / 3) as u8
}